def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    negative_2019 = v1 < 0
    negative_2018 = v2 < 0

    if negative_2019 and not negative_2018:
        result = 2019
    elif negative_2018 and not negative_2019:
        result = 2018
    elif negative_2019 and negative_2018:
        result = [2019, 2018]
    else:
        result = None

    return {
        "value": result,
        "trace": {
            "intangible_assets_2019": v1,
            "intangible_assets_2018": v2,
            "negative_2019": negative_2019,
            "negative_2018": negative_2018,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
